<?php ini_set('display_errors', 1); error_reporting(E_ALL); require_once __DIR__ . '/config/env.php'; try { \ = new PDO('mysql:host='.DB_HOST.';dbname='.DB_NAME.';charset=utf8mb4', DB_USER, DB_PASS, [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]); echo 'SUCCESS'; } catch(PDOException \) { echo 'ERROR: ' . \->getMessage(); } catch(Throwable \) { echo 'FATAL: ' . \->getMessage(); }